begin;

-- Day 15: The Anchor Check
update public.lessons set
  duration_seconds = 267,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_15/lesson_15_seg_01.mp3"],"total_audio_seconds":87.28,"timed_text":[{"start_s":0.0,"text":"May 15th, you chose your focus anchor earlier in this program,"},{"start_s":5.16,"text":"a word or phrase your mind returns to when it starts to drift."},{"start_s":9.48,"text":"Today I want to take that further,"},{"start_s":11.48,"text":"because the most powerful version of an anchor"},{"start_s":15.0,"text":"isn''t just a word in your head."},{"start_s":17.12,"text":"It''s something physical, something that exists"},{"start_s":19.72,"text":"in the actual space where you compete."},{"start_s":22.6,"text":"Elite athletes do this instinctively,"},{"start_s":25.52,"text":"a basketball player who bounces the ball exactly three times"},{"start_s":28.92,"text":"before a free throw, a sprinter who locks eyes"},{"start_s":31.72,"text":"on the same spot on the track before the gun."},{"start_s":34.64,"text":"A quarterback who taps his wrist band"},{"start_s":36.88,"text":"before walking to the line,"},{"start_s":38.8,"text":"these aren''t superstitions."},{"start_s":40.28,"text":"They''re trained to focus triggers,"},{"start_s":42.44,"text":"physical anchors that pull the mind back"},{"start_s":45.28,"text":"to the present moment on command."},{"start_s":48.01,"text":"The key is consistency."},{"start_s":50.88,"text":"The same thing the same way every single time,"},{"start_s":54.24,"text":"because your nervous system responds to patterns."},{"start_s":57.8,"text":"When you perform that cue enough times in a focus state,"},{"start_s":61.28,"text":"the cue begins to trigger the state."},{"start_s":64.12,"text":"That is conditioning."},{"start_s":66.79,"text":"That''s what we''re building today."},{"start_s":69.26,"text":"Think about the physical environment where you compete."},{"start_s":72.52,"text":"What is something you can see, touch, feel or do?"},{"start_s":77.31,"text":"Something that is always available in that space"},{"start_s":80.19,"text":"that you can turn into your competition anchor."},{"start_s":83.93,"text":"On your screen, you''re gonna identify it and lock it in."}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"Think about the physical space where you compete. What do you see, hear, or feel in that environment that is always there — every competition, every time?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Identify your physical anchor — something in that space, or something you wear or carry, that you can use as a consistent focus trigger. Something you can touch, see, or do deliberately before or during competition.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Design the moment — exactly when in competition will you use this anchor? Between plays? Before the starting signal? After a mistake? Write the specific moment and the exact action.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Say your focus word once. Feel your attention settle. That word plus that physical anchor — those two together are your return to center.","min_entry_seconds":0}],"summary":{"display":"all","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_15/lesson_15_seg_02.mp3"],"total_audio_seconds":20.14,"timed_text":[{"start_s":0.0,"text":"Every time you use the physical anchor, you''re strengthening the connection between that"},{"start_s":4.4,"text":"action and your focus state."},{"start_s":6.84,"text":"Do it in practice, do it in warm-ups, do it in competition."},{"start_s":11.2,"text":"The more consistent you are, the faster it works when the pressure is real."},{"start_s":16.3,"text":"Check out the journal and have to be finished, day 15 is complete."}]},{"type":"journal_prompt","prompt":"What physical anchor did you choose — and why does that specific thing feel right for your competition environment?"}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000015';

-- Day 16: The Traffic Light System
update public.lessons set
  duration_seconds = 259,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_16/lesson_16_seg_01.mp3"],"total_audio_seconds":82.76,"timed_text":[{"start_s":0.0,"text":"Day 16, one of the most practical tools I''ve ever come across in sports psychology, comes"},{"start_s":7.0,"text":"from the great Bill Bessie."},{"start_s":9.76,"text":"He calls it the traffic light system, green, amber, red."},{"start_s":15.76,"text":"Green is where you want to compete, relaxed in the flow."},{"start_s":20.6,"text":"System one is running the show."},{"start_s":22.56,"text":"You''re executing without overthinking."},{"start_s":25.56,"text":"Your body trusts your training."},{"start_s":27.88,"text":"This is what flow state looks like."},{"start_s":30.38,"text":"Amber or yellow is the warning state."},{"start_s":33.26,"text":"You''re starting to feel the fatigue, the frustration, the pressure, and your focus is starting"},{"start_s":37.9,"text":"to drift."},{"start_s":39.42,"text":"You''re not in the red yet, but you''re heading there."},{"start_s":42.18,"text":"So yellow are amber is where the tools matter most."},{"start_s":45.66,"text":"Because if you catch yourself here, you can course correct before the spiral starts."},{"start_s":51.1,"text":"That is where performance goes to die, dominated by a negative self-talk, poor decisions,"},{"start_s":56.66,"text":"emotional reactions instead of train responses."},{"start_s":60.86,"text":"So once you''re in the red in competition, it takes significant effort to come back."},{"start_s":66.26,"text":"Most athletes don''t know where they are."},{"start_s":68.06,"text":"They just feel bad and can''t explain why."},{"start_s":70.9,"text":"The traffic light gives you a language for your own psychological state and a plan for"},{"start_s":75.54,"text":"each one."},{"start_s":77.27,"text":"On your screen, you''re going to learn what each state looks and feels like specifically"},{"start_s":81.87,"text":"for you."}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"Describe what GREEN feels like for you in competition — physically, mentally, emotionally. What are the specific signs that you are in your optimal performance state?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Describe AMBER — the warning signs that tell you your state is slipping. What do you notice first? Is it physical tension, a specific thought, a change in your breathing?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Describe RED — what it looks and feels like when you''ve lost the mental battle. What are the unmistakable signs for you specifically?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"For AMBER only — when you notice those warning signs, what is your first move? Which tool do you use to bring yourself back before you hit red?","min_entry_seconds":0}],"summary":{"display":"all","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_16/lesson_16_seg_02.mp3"],"total_audio_seconds":16.72,"timed_text":[{"start_s":0.0,"text":"The goal isn''t always to be in the green."},{"start_s":3.45,"text":"That''s just not realistic."},{"start_s":5.41,"text":"The goal is to recognize Amber Yellow before it becomes red"},{"start_s":10.05,"text":"and to have a tool ready when it does."},{"start_s":12.75,"text":"Check out the journal in after you finish,"},{"start_s":14.45,"text":"Day 16 is complete."}]},{"type":"journal_prompt","prompt":"In your last competition, were you mostly green, amber, or red? At what point did your state shift — and what caused it?"}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000016';

-- Day 17: First Things First
update public.lessons set
  duration_seconds = 241,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_17/lesson_17_seg_01.mp3"],"total_audio_seconds":92.87,"timed_text":[{"start_s":0.0,"text":"Day 17."},{"start_s":1.96,"text":"Before we go any deeper into competition performance, I need to ask you something."},{"start_s":7.13,"text":"Why are you doing this?"},{"start_s":9.41,"text":"Not the athletic goals, not the starting spot or the stats or the scholarship."},{"start_s":14.81,"text":"I mean the bigger picture."},{"start_s":16.85,"text":"What are the things in your life that matter most?"},{"start_s":19.57,"text":"The people, the relationships, the responsibilities that your athletic career supposed"},{"start_s":24.41,"text":"to serve?"},{"start_s":26.06,"text":"Bill Bessick calls this, keeping the first things first."},{"start_s":30.02,"text":"And what he found working with professional athletes at the highest level is that the"},{"start_s":34.14,"text":"ones who burn out or lose motivation or who hit performance plateaus that can''t climb"},{"start_s":38.94,"text":"out of, they''ve usually lost their connection to their why."},{"start_s":43.4,"text":"When sport becomes the only thing, it becomes the wrong thing."},{"start_s":48.76,"text":"Because sport is not the point."},{"start_s":51.16,"text":"Sport is just the vehicle."},{"start_s":53.04,"text":"The relationships you build through it, the character develops, the future it creates,"},{"start_s":58.64,"text":"that''s the point."},{"start_s":60.04,"text":"Family, friends, health, academics, the people counting on you."},{"start_s":67.02,"text":"The version of yourself, you''re building beyond the field."},{"start_s":70.8,"text":"When you stay connected to that, when you compete for something bigger than the scoreboard,"},{"start_s":76.79,"text":"you''re tougher to break because the foundation is bigger than any outcome."},{"start_s":81.71,"text":"On your screen, you''re going to name your first things."},{"start_s":85.15,"text":"The ones that matter most regardless of whether you have ever, the ones that matter most"},{"start_s":90.07,"text":"regardless of whether you ever play another game."}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"Family — Who are the people in your family that your athletic journey is connected to? Why does competing well matter when you think about them?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Friends and teammates — Who in your life shows up for you regardless of performance? Why do those relationships matter to how you compete?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Health — Your body is the vehicle. What does taking care of it mean to you beyond sport — for the life you''re building after the final game?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Academics and future — What are you building outside the lines? Why does the person you''re becoming in the classroom and in the real world matter?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Now — write one sentence: ''I compete because...'' Let it be honest. Let it be bigger than wins and losses.","min_entry_seconds":0}],"summary":{"display":"all","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_17/lesson_17_seg_02.mp3"],"total_audio_seconds":23.82,"timed_text":[{"start_s":0.0,"text":"That why is now saved in your profile? Read it when competition stops feeling worth it. Read it when the"},{"start_s":8.27,"text":"training is hard and the results aren''t showing up yet. The athletes who last, who keep competing at a high"},{"start_s":14.51,"text":"level when everything gets difficult, they''ve never lost their connection to that answer. After you"},{"start_s":20.98,"text":"finish, day 17 is complete."}]}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000017';

-- Day 18: The If-Then Plan
update public.lessons set
  duration_seconds = 161,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_18/lesson_18_seg_01.mp3"],"total_audio_seconds":70.27,"timed_text":[{"start_s":0.0,"text":"18. One of the biggest reasons athletes break in big moments is that they''ve never planned"},{"start_s":6.48,"text":"for them. Not the success, the worst case. What happens if you fall behind early? What happens"},{"start_s":13.65,"text":"if you make a visible error in front of the biggest crowd you''ve ever competed in front of?"},{"start_s":18.37,"text":"What happens if your body starts to give out before the competition is over? Most athletes avoid"},{"start_s":23.5,"text":"those questions. They think planning for failure invites it. That''s backwards."},{"start_s":29.18,"text":"Planning for adversity is what makes you dangerous because now you have a response ready"},{"start_s":33.98,"text":"before the moment hits. This is the then plan. If x happens, then I do y. It''s not pessimism,"},{"start_s":42.3,"text":"it''s preparation. Research is clear on this. Athletes who pre-planned responses to adversity"},{"start_s":49.47,"text":"recover faster and perform more consistently than athletes who respond in the moment without a"},{"start_s":55.71,"text":"plan. You''re not hoping the bad thing doesn''t happen. You''re deciding in advance that it"},{"start_s":60.98,"text":"doesn''t own you. On your screen, you''re going to build your if-then plan for the three most likely"},{"start_s":67.23,"text":"adversity scenarios in your sport."}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"What is the most likely thing to go wrong in your next competition — the one that typically starts your mental spiral? Describe the scenario and write your exact response: breath, reset word, refocus.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Second most likely adversity scenario — and your response.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Third scenario — and your response.","min_entry_seconds":0}],"summary":{"display":"all","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_18/lesson_18_seg_02.mp3"],"total_audio_seconds":16.69,"timed_text":[{"start_s":0.0,"text":"You just made three decisions in advance."},{"start_s":3.6,"text":"When those moments arrive and they will,"},{"start_s":6.68,"text":"your brain already has the answer."},{"start_s":9.08,"text":"No freeze, no spiral, just the plan."},{"start_s":13.62,"text":"Now let you finish, day 18 is complete."}]}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000018';

-- Day 19: Reframe — When Your Mind Broke
update public.lessons set
  duration_seconds = 171,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_19/lesson_19_seg_01.mp3"],"total_audio_seconds":80.9,"timed_text":[{"start_s":0.0,"text":"A19, today we do something different."},{"start_s":3.68,"text":"There''s a moment in your competitive career"},{"start_s":6.4,"text":"where your mind completely broke on you."},{"start_s":10.0,"text":"Your focus left, the spiral started."},{"start_s":12.96,"text":"You couldn''t come back."},{"start_s":14.56,"text":"And the performance suffered because of it."},{"start_s":17.71,"text":"You''ve probably replayed that moment as a failure."},{"start_s":20.99,"text":"What if you replayed it as a training opportunity instead?"},{"start_s":24.63,"text":"You cannot achieve greatness without mistakes."},{"start_s":28.03,"text":"The question isn''t whether you make errors."},{"start_s":30.83,"text":"Bill Bezick puts it this way."},{"start_s":32.87,"text":"You cannot achieve greatness without mistakes."},{"start_s":35.55,"text":"The question isn''t whether you make errors."},{"start_s":37.95,"text":"The question is whether you''re big enough to accept them,"},{"start_s":40.63,"text":"learn from them, and refuse to let them define you."},{"start_s":44.11,"text":"That''s what we''re doing today."},{"start_s":45.87,"text":"Retrospective reframing."},{"start_s":48.47,"text":"Not pretending that bad moments didn''t happen."},{"start_s":51.67,"text":"Updating your brain''s response to it"},{"start_s":53.55,"text":"with the tools you now have."},{"start_s":55.93,"text":"Every time you do this, that memory loses a little more"},{"start_s":59.21,"text":"of its charge."},{"start_s":60.61,"text":"And the next time something similar happens in competition,"},{"start_s":63.89,"text":"your brain looks for the train response,"},{"start_s":66.29,"text":"not the old panic pattern."},{"start_s":69.46,"text":"Think of a specific moment."},{"start_s":72.1,"text":"One that still has some weight to it."},{"start_s":74.54,"text":"This caused you a lot of pain, a lot of anguish."},{"start_s":77.38,"text":"Oh, next on your screen, you''re going to walk right through it."}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"Describe the moment — the situation, what happened, what your mind did, and how it affected your performance.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"At what exact point did the spiral begin? What was the first thought that started the chain?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"With the tools you have now — your reset word, your reset protocol, your focus anchor, your If-Then plan — what would you have done differently? Walk through it step by step.","min_entry_seconds":0}],"summary":{"display":"all","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_19/lesson_19_seg_02.mp3"],"total_audio_seconds":15.46,"timed_text":[{"start_s":0.0,"text":"that moment just became a rep. The next time something like that arrives in competition,"},{"start_s":6.06,"text":"your brain already has a response. You''ve been there. And now you come out the other side."},{"start_s":12.38,"text":"Now that you''re finished, day 19 is complete."}]}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000019';

-- Day 20: Embracing the Suffer
update public.lessons set
  duration_seconds = 233,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_20/lesson_20_seg_01.mp3"],"total_audio_seconds":84.66,"timed_text":[{"start_s":0.0,"text":"day 20."},{"start_s":2.46,"text":"I want to ask you something that the best coaches in the world ask every athlete they work"},{"start_s":7.34,"text":"with."},{"start_s":8.76,"text":"How much are you willing to not tolerate suffer?"},{"start_s":12.08,"text":"The discomfort of a hard training block, the exhaustion of competing when your body has nothing"},{"start_s":17.36,"text":"left, the psychological pain of being behind, being doubted, of fighting for something that"},{"start_s":23.96,"text":"isn''t guaranteed."},{"start_s":26.3,"text":"My achievement inherently involves discomfort."},{"start_s":30.22,"text":"That''s not a side effect of greatness."},{"start_s":32.22,"text":"It''s the price of admission."},{"start_s":34.82,"text":"Here''s what acceptance means in the context of sport."},{"start_s":38.28,"text":"It doesn''t mean you like the hard parts."},{"start_s":40.68,"text":"It means you stop treating the hard parts as signals to stop."},{"start_s":44.62,"text":"You accept that they''re present, the fatigue, the doubt, the fear, and you compete alongside"},{"start_s":50.54,"text":"them instead of waiting for them to go away."},{"start_s":53.22,"text":"They don''t go away."},{"start_s":54.74,"text":"The athletes who win championships aren''t the ones who stopped feeling the pressure."},{"start_s":59.34,"text":"They''re the ones who kept moving through it."},{"start_s":61.62,"text":"I want you to face that question directly."},{"start_s":64.5,"text":"Not to inspire you to prepare you because when the suffering arrives and it will, the athlete"},{"start_s":71.34,"text":"who has already said, I know this is coming and I''m choosing it anyway, handles it completely"},{"start_s":77.26,"text":"different than the one who''s surprised by it."},{"start_s":80.64,"text":"From your screen, you''re going to answer three core questions, honestly."}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"What do you want? Not what you''re supposed to want — what do you actually want from your athletic career? Be honest and specific.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"How badly do you want it? What is the evidence in your daily behavior that you want it at that level? Not intentions — actual actions.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"How much will you suffer for it? What are you willing to go through — physically, mentally, emotionally — to get to where you''re trying to go?","min_entry_seconds":0}],"summary":{"display":"all","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_20/lesson_20_seg_02.mp3"],"total_audio_seconds":13.35,"timed_text":[{"start_s":0.0,"text":"Those three answers are your commitment contract with yourself."},{"start_s":4.8,"text":"Not with your coaches, not with your team, with yourself."},{"start_s":8.96,"text":"Check out the next journal and after you finish, day 20 is complete."}]},{"type":"journal_prompt","prompt":"Where is the gap between what you say you want and how you''re actually training for it? What does closing that gap require?"}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000020';

-- Day 21: The Fighter Mindset
update public.lessons set
  duration_seconds = 167,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_21/lesson_21_seg_01.mp3"],"total_audio_seconds":92.32,"timed_text":[{"start_s":0.0,"text":"day 21. When you face a challenge, a big competition, a moment of adversity, something that"},{"start_s":8.58,"text":"tests you, your brain does something automatic. It imagines the worst case, embarrassment, failure,"},{"start_s":16.72,"text":"loss, that fear scenario. That''s not weakness. That''s your nervous system doing exactly"},{"start_s":23.55,"text":"what it was designed to do. That threat response is ancient. It was built to keep you"},{"start_s":29.53,"text":"alive. And it still fires the same way whether you''re facing a predator or stepping on"},{"start_s":35.61,"text":"the starting line. There are two types of athletes in those moments. The victim and the fighter."},{"start_s":43.13,"text":"The victim acknowledges the fear and becomes it. They make excuses. They shrink. They find"},{"start_s":50.76,"text":"reasons why the situation is unfair or why they''re not ready. And they stay on the safe side of"},{"start_s":56.81,"text":"the line. The fighter acknowledges the same fear and steps over the line anyway. Because"},{"start_s":64.12,"text":"they''re not afraid because they decided the fear doesn''t get to make the call. The difference isn''t"},{"start_s":70.2,"text":"talent. It isn''t physical preparation. It''s a decision made in the seconds before the whistle"},{"start_s":76.78,"text":"blows about who gets to be in charge. You or the fear. You''ve been building the tools to make"},{"start_s":82.78,"text":"that decision automatically. Today we name it explicitly on your screen to go into identify"},{"start_s":88.7,"text":"your line and declare which side you choose."}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"Describe the fear you feel before your most challenging competitive moments. Be specific — what does it say? What worst-case scenario does your brain go to?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Now name it for what it is — your brain trying to protect you. It''s not the truth. It''s a signal.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"The fighter steps over the line anyway. What does stepping over the line look like for you — specifically, in the moment that fear arrives?","min_entry_seconds":0}],"summary":{"display":"all","header":"","hold_seconds":0}}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000021';

-- Day 22: Visualization — See the Outcome
update public.lessons set
  duration_seconds = 280,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_22/lesson_22_seg_01.mp3"],"total_audio_seconds":59.61,"timed_text":[{"start_s":0.0,"text":"Today we start with visualization and this was one of the highest leverage tools in the entire program."},{"start_s":8.0,"text":"Research shows that mental imagery activates the same neural pathways as physical execution."},{"start_s":16.32,"text":"Your brain doesn''t cleanly distinguish between a vivid visualization and the real thing."},{"start_s":23.38,"text":"Every visualization rep is a real training rep."},{"start_s":27.64,"text":"I build custom visualization scripts for every athlete I coach one on one, built specifically around your sport position and competitive scenarios."},{"start_s":36.64,"text":"We start with outcome visualization."},{"start_s":38.64,"text":"You need to be able to see yourself succeeding before you can train yourself to execute the process that gives you there."},{"start_s":45.67,"text":"The more sensory detail you build, the sights, the sounds, the physical sensations, the more powerful it becomes."},{"start_s":53.67,"text":"On your screen we start with one breath and then you''re going to close your eyes and build the scene."}]},{"type":"timed_exercise","duration_seconds":16,"interactive_model":"box_breathing","visual_cues":["One full cycle. Settle in.","Follow the circle."],"steps":[{"text":"Inhale","duration_seconds":4,"haptic":"heavy"},{"text":"Hold","duration_seconds":4,"haptic":"light"},{"text":"Exhale","duration_seconds":4,"haptic":"heavy"},{"text":"Hold","duration_seconds":4,"haptic":"light"}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"Close your eyes. Place yourself in your next competition. Build every detail of the environment.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"What do you hear? The crowd, your teammates, the sounds specific to your sport.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Feel your body. What does it feel like to be moving well? What does that sensation feel like?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"See the moment — the execution, the result. Watch yourself succeed. Hold it.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"How does it feel when it happens? Stay there.","min_entry_seconds":0}],"summary":{"display":"all","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_22/lesson_22_seg_02.mp3"],"total_audio_seconds":19.7,"timed_text":[{"start_s":0.0,"text":"Your brain just treated that as a real performance rep."},{"start_s":3.78,"text":"Do this before every competition."},{"start_s":6.23,"text":"Build the image until it feels familiar."},{"start_s":8.87,"text":"Because when it''s familiar, it''s less threatening."},{"start_s":12.31,"text":"And when it''s less threatening, you compete free."},{"start_s":16.44,"text":"Hit the journal and after you finish, day 22 is complete."}]},{"type":"journal_prompt","prompt":"How vivid was the visualization? What detail made it feel most real — and what was hardest to hold?"}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000022';

-- Day 23: Your Visualization Board
update public.lessons set
  duration_seconds = 215,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_23/lesson_23_seg_01.mp3"],"total_audio_seconds":76.98,"timed_text":[{"start_s":0.0,"text":"A 23, commitment is about directing your behavior toward your values, not when you feel"},{"start_s":7.16,"text":"like it every day."},{"start_s":10.34,"text":"One of the most powerful ways to stay anchored to your values is to make them visible."},{"start_s":16.46,"text":"To build a picture of the life and the athlete you''re committed to becoming, and put it"},{"start_s":20.58,"text":"somewhere you see every single day."},{"start_s":24.54,"text":"Research on visual goal representation shows that when the brain is repeatedly exposed"},{"start_s":30.06,"text":"to images of a desired outcome, it begins to prioritize the information and opportunities"},{"start_s":36.62,"text":"that align with it."},{"start_s":38.52,"text":"Your attention starts to organize around what you see consistently."},{"start_s":43.62,"text":"What you see consistently, you move toward."},{"start_s":47.35,"text":"But this only works if it''s real, not generic inspiration, specific images and words that"},{"start_s":53.43,"text":"represent your athletic goals, your identity, the life your committed to build."},{"start_s":59.27,"text":"There''s Canva, images on the internet, words, whatever it takes, but build something"},{"start_s":64.83,"text":"that when you look at it, you feel the pull of it."},{"start_s":68.63,"text":"The version of yourself on the other side of the work."},{"start_s":71.75,"text":"On your screen, you''ll find the visualization board tool."},{"start_s":76.07,"text":"Take your time."}]},{"type":"visualization_board","ambient_audio":"ambient/ambient_music.mp3","prompt":"Build a picture of the athlete you''re committing to becoming. Your goals. Your why. Your future. Make it specific enough that looking at it every day means something.","pull_from_profile":["identity_statement","core_why"],"save_to_profile":true},{"type":"voiceover","audio_files":["lesson_23/lesson_23_seg_02.mp3"],"total_audio_seconds":18.18,"timed_text":[{"start_s":0.0,"text":"That board lives on your home screen now."},{"start_s":2.8,"text":"Look at it every morning before you train,"},{"start_s":5.28,"text":"look at it the night before competition,"},{"start_s":7.36,"text":"look at it when the work gets hard"},{"start_s":8.8,"text":"and the results aren''t showing up yet."},{"start_s":11.71,"text":"That''s not decoration, that''s a commitment device."},{"start_s":15.59,"text":"After you finish, day 23 is complete."}]}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000023';

-- Day 24: Raise Your Bottom Line
update public.lessons set
  duration_seconds = 231,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_24/lesson_24_seg_01.mp3"],"total_audio_seconds":86.1,"timed_text":[{"start_s":0.0,"text":"They 24 most athletes aim for perfection."},{"start_s":4.68,"text":"And I understand why, but perfection as a standard"},{"start_s":8.12,"text":"is actually one of the most damaging things"},{"start_s":10.52,"text":"you can chase because the gap between your best"},{"start_s":13.64,"text":"and your average becomes a constant source of shame."},{"start_s":18.38,"text":"Here''s a better target."},{"start_s":19.98,"text":"Raise your bottom line."},{"start_s":23.1,"text":"Here''s what that means."},{"start_s":24.62,"text":"Every athlete has a range."},{"start_s":26.94,"text":"They''re best days and they''re worst days."},{"start_s":29.82,"text":"The question isn''t how high your ceiling is."},{"start_s":32.56,"text":"The question is, how high is your floor?"},{"start_s":37.19,"text":"If your worst competitive performance"},{"start_s":39.35,"text":"is operating at 60% of your capability,"},{"start_s":42.59,"text":"that''s your bottom line."},{"start_s":44.62,"text":"And what I''ve seen working with athletes at every level"},{"start_s":46.94,"text":"is that the ones who compound over time"},{"start_s":50.02,"text":"are the ones who commit to the fundamentals so consistently"},{"start_s":54.22,"text":"that their floor rises, not their ceiling, their floor."},{"start_s":58.76,"text":"Their worst days become 75%, then 85%."},{"start_s":64.16,"text":"That compounding happens not through heroic efforts"},{"start_s":67.32,"text":"on game day."},{"start_s":68.52,"text":"It happens through the daily behaviors."},{"start_s":70.88,"text":"The routine, the evidence log, the mental reps"},{"start_s":74.12,"text":"that you build when nobody''s watching."},{"start_s":77.02,"text":"The commitment isn''t to be perfect."},{"start_s":79.26,"text":"It''s to be reliable."},{"start_s":81.7,"text":"On your screen, you''re gonna look at your current floor"},{"start_s":84.14,"text":"and commit to raising it."}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"Honestly — what does your worst competitive performance look like right now? Not your fear of what it could be. What does it actually look like on a bad day?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"What are the specific daily behaviors that, if you did them consistently, would raise that floor? Not the big things — the small, repeatable ones.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Commit to one behavior from that list that you will do every single day for the rest of this program — not because you feel like it, but because that''s how the floor rises.","min_entry_seconds":0}],"summary":{"display":"all","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_24/lesson_24_seg_02.mp3"],"total_audio_seconds":10.74,"timed_text":[{"start_s":0.0,"text":"Commit to your worst day being good enough."},{"start_s":3.08,"text":"Because when your floor is solid,"},{"start_s":4.88,"text":"your ceiling takes care of itself."},{"start_s":7.12,"text":"Go hit the journal and when you finish,"},{"start_s":9.24,"text":"day 24 is complete."}]},{"type":"journal_prompt","prompt":"What would change about how you compete if you stopped chasing your best day and started committing to your most reliable day?"}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000024';

-- Day 25: The Mistake Protocol
update public.lessons set
  duration_seconds = 229,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_25/lesson_25_seg_01.mp3"],"total_audio_seconds":65.55,"timed_text":[{"start_s":0.0,"text":"Day 25"},{"start_s":2.19,"text":"What happens in the five seconds after a mistake determines more about your performance than the mistake itself"},{"start_s":9.49,"text":"Here''s the pattern"},{"start_s":11.55,"text":"Athlete makes error"},{"start_s":12.91,"text":"Brain fires immediately"},{"start_s":14.91,"text":"Replays the mistake"},{"start_s":17.01,"text":"Catastrophises"},{"start_s":19.17,"text":"The consequences"},{"start_s":22.26,"text":"Athlete carries that weight into the next play"},{"start_s":25.71,"text":"Next play breaks down spiral"},{"start_s":28.39,"text":"The mistake didn''t cost them the five seconds after did"},{"start_s":34.13,"text":"Your job in those five seconds is one thing"},{"start_s":37.09,"text":"Interruption you are not processing the mistake. You are not evaluating what went wrong. You have one job get back to the next play"},{"start_s":46.1,"text":"Three steps"},{"start_s":47.54,"text":"Reset word say it physical cue"},{"start_s":50.82,"text":"Run it focus anchor return to it five seconds back in the game"},{"start_s":57.17,"text":"Today you''re drilling that sequence three times back to back until it''s locked"},{"start_s":61.65,"text":"On your screen you''re going to walk through it right now"}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"A mistake just happened. 5 seconds. Step 1 — your reset word. Say it now.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Step 2 — your physical cue. Run it right now.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Step 3 — your focus anchor. Return to it. You''re here. Next play.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Again. Mistake. Reset word. Physical cue. Focus anchor.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"One more time. All three steps. Locked.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Describe what running that sequence felt like. Did it interrupt the spiral? What was hardest to execute?","min_entry_seconds":0}],"summary":{"display":"last","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_25/lesson_25_seg_02.mp3"],"total_audio_seconds":13.93,"timed_text":[{"start_s":0.0,"text":"Drill that protocol and practice this week."},{"start_s":3.23,"text":"Make an intentional error and run it."},{"start_s":6.69,"text":"Make it automatic before competition demands it."},{"start_s":10.05,"text":"After you finish, day 25 is complete."}]}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000025';

-- Day 26: Reframe — What You Would Do Differently
update public.lessons set
  duration_seconds = 242,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_26/lesson_26_seg_01.mp3"],"total_audio_seconds":69.18,"timed_text":[{"start_s":0.0,"text":"Day 26"},{"start_s":2.1,"text":"We did a reframe exercise earlier in the series. Today. We go deeper"},{"start_s":7.3,"text":"You''ve added tool since then like your reset word your if then plan yourself talk replacements"},{"start_s":14.7,"text":"Your mistake protocol the fighter mindset your focus anchors trained"},{"start_s":20.86,"text":"I want you to go back to a different moment"},{"start_s":24.14,"text":"Competition that didn''t go the way you wanted where your mind got in the way"},{"start_s":28.26,"text":"When you''ve carried as a failure"},{"start_s":30.7,"text":"We''re going to replay it not to relive the pain but to rewrite the response"},{"start_s":36.81,"text":"This is a specific skill"},{"start_s":39.21,"text":"You''re not pretending the bad moment didn''t happen"},{"start_s":42.49,"text":"You''re showing your nervous system that you now have a trained answer to the moment that used to have none"},{"start_s":49.65,"text":"Every time you do this that memory loses its charge and the next time something similar arrives your brain looks for the trained response"},{"start_s":58.69,"text":"Not the old pattern think of a moment that still stings a little yeah, that''s the one on your screen you''re gonna walk through it"}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"Describe the moment — the situation, what happened, what your mind did, and how it affected your performance.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"At what exact point did the spiral begin? What was the trigger thought?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Replay it with your full toolkit. From that exact moment — walk through what you would have done. Every step. Reset word, physical cue, focus anchor, self-talk replacement. Be specific.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Read your reframed response back. This is your trained answer to that moment now.","min_entry_seconds":0}],"summary":{"display":"all","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_26/lesson_26_seg_02.mp3"],"total_audio_seconds":12.94,"timed_text":[{"start_s":0.0,"text":"So look that memory just became an actual rep and the next time something like it arrives"},{"start_s":5.52,"text":"look you''ve already been there with a plan next you''ve got a journal and after you finish day 26 is complete"}]},{"type":"journal_prompt","prompt":"How did it feel to give your brain a trained response for that moment? Did the weight of that memory change at all?"}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000026';

-- Day 27: What's Next?
update public.lessons set
  duration_seconds = 166,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_27/lesson_27_seg_01.mp3"],"total_audio_seconds":77.38,"timed_text":[{"start_s":0.0,"text":"day 27. I want to leave you with a question that I want you to carry for the rest of your career."},{"start_s":6.78,"text":"What''s next? Not what did I achieve? What''s next? Here''s why this matters. One of the biggest"},{"start_s":16.27,"text":"performance killers in sport is complacency after success. You achieve something, you make the team,"},{"start_s":24.03,"text":"you get the starting spot, you hit a personal best, and without realizing it,"},{"start_s":28.43,"text":"your standards quietly drop. Because part of your brain thinks the job is done."},{"start_s":33.95,"text":"The what''s next habit prevents that. It builds the mindset of continuous growth."},{"start_s":40.27,"text":"Of setting new limits the moment you reach the old ones. Of understanding that achievement is"},{"start_s":44.91,"text":"not a destination, it''s a direction. The athletes who sustain elite performance over years and"},{"start_s":51.54,"text":"seasons are not the ones who were satisfied with what they built. They were the ones who used"},{"start_s":56.98,"text":"each achievement as a launching pad for the next standard. You''re three days from completing"},{"start_s":64.16,"text":"this whole program. And the most important thing that can tell you is this. Finishing is not the goal."},{"start_s":70.4,"text":"The next chapter is on your screen. You''re going to answer the prompted question."}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"What have you built over the last 27 days that you didn''t have when you started?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"What is the next standard you''re committing to? Not a wish — a specific, behavioral commitment that starts the day after this program ends.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"What''s next? Write it as a declaration. ''After this program, I commit to...''","min_entry_seconds":0}],"summary":{"display":"all","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_27/lesson_27_seg_02.mp3"],"total_audio_seconds":14.06,"timed_text":[{"start_s":0.0,"text":"What''s next?"},{"start_s":2.13,"text":"Keep asking that question."},{"start_s":4.13,"text":"Every achievement, every season, every milestone."},{"start_s":7.16,"text":"The answer to that question is where the growth lives."},{"start_s":10.16,"text":"Now that you''re finished, day 27 is complete."}]}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000027';

-- Day 28: Identity Under Pressure
update public.lessons set
  duration_seconds = 181,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_28/lesson_28_seg_01.mp3"],"total_audio_seconds":67.3,"timed_text":[{"start_s":0.0,"text":"day 28, who are you in a guitar? Not who you are in your best day, not who you want to be,"},{"start_s":8.38,"text":"who are you when you''re behind in the fourth quarter, when you''ve made two mistakes back to back,"},{"start_s":13.58,"text":"when the biggest competition of your season is on the line and everything in your body is asking"},{"start_s":18.38,"text":"you to quit. Think back to where you were when this journey started. There was probably a"},{"start_s":24.22,"text":"version of you that didn''t have an answer for that question. That defaulted to the situation,"},{"start_s":30.54,"text":"that got swallowed by the moment. You''ve been building the answer for 28 days."},{"start_s":36.46,"text":"The mental training doesn''t change you in the comfortable moments. It reveals you in the difficult"},{"start_s":42.38,"text":"ones. Every rep you''ve put in has been preparing you for exactly that moment, the one that"},{"start_s":48.77,"text":"used to break you. Today I want you to write your competition identity, not a general statement."},{"start_s":57.76,"text":"The version of you that shows up when the game is on the line and everything is against you."},{"start_s":63.22,"text":"On your screen, we''re going to take a breath and then we write."}]},{"type":"timed_exercise","duration_seconds":16,"interactive_model":"box_breathing","visual_cues":["One full cycle. Settle in.","Follow the circle."],"steps":[{"text":"Inhale","duration_seconds":4,"haptic":"heavy"},{"text":"Hold","duration_seconds":4,"haptic":"light"},{"text":"Exhale","duration_seconds":4,"haptic":"heavy"},{"text":"Hold","duration_seconds":4,"haptic":"light"}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"Write your competition identity statement — specifically for your hardest moment. Who are you when the game is on the line, you''re behind, and everything hurts? Present tense. ''I am an athlete who...''","min_entry_seconds":0}],"summary":{"display":"last","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_28/lesson_28_seg_02.mp3"],"total_audio_seconds":13.69,"timed_text":[{"start_s":0.0,"text":"Read that before every competition from here forward."},{"start_s":3.76,"text":"Not as a wish as a reminder of a decision you''ve already made."},{"start_s":8.69,"text":"You have a journal prompt and after you finish day 28 is complete."}]},{"type":"journal_prompt","prompt":"When was the last time you actually lived out that identity in competition? What made it possible?"}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000028';

-- Day 29: Reframe — Turning Adversity Into Fuel
update public.lessons set
  duration_seconds = 189,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_29/lesson_29_seg_01.mp3"],"total_audio_seconds":75.11,"timed_text":[{"start_s":0.0,"text":"Day 29, one last reframe, and this one goes the broadest."},{"start_s":6.89,"text":"The first two reframe exercises were about specific moments."},{"start_s":11.29,"text":"Today I want you to think bigger."},{"start_s":13.09,"text":"A period in your athletic career, a season, a stretch of months, maybe longer, where"},{"start_s":18.81,"text":"it felt like everything was working against you, injuries, a coaching change, losing your"},{"start_s":24.7,"text":"position, a performance slump you couldn''t climb out of."},{"start_s":29.18,"text":"First athletes carry that period as evidence against themselves."},{"start_s":33.48,"text":"That''s when I found out I wasn''t as good as I thought."},{"start_s":36.36,"text":"That''s when things started going wrong."},{"start_s":39.1,"text":"And here''s what I''ve seen working with athletes who''ve been through that."},{"start_s":41.9,"text":"The ones who''d come out on the other side and competed at a higher level, they didn''t"},{"start_s":45.86,"text":"avoid the adversity."},{"start_s":47.82,"text":"They extracted from it."},{"start_s":49.73,"text":"The hard period didn''t break them."},{"start_s":52.01,"text":"It built the part of them that''s unbreakable."},{"start_s":55.32,"text":"You cannot achieve greatness without going through the difficult parts."},{"start_s":59.44,"text":"The suffering isn''t a detour."},{"start_s":61.76,"text":"It''s the training."},{"start_s":63.67,"text":"Think about your hardest stretch."},{"start_s":65.99,"text":"Not to relive it to extract what it actually built."},{"start_s":71.1,"text":"On your screen, go ahead and walk through it more time."}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"Describe the hardest stretch of your athletic career. What was happening? What made it difficult?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"What did that period demand of you mentally that nothing else had before?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"What did you prove about yourself by getting through it — even if it didn''t feel that way at the time?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Write one sentence: what that period built in you that you now compete with.","min_entry_seconds":0}],"summary":{"display":"all","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_29/lesson_29_seg_02.mp3"],"total_audio_seconds":14.35,"timed_text":[{"start_s":0.0,"text":"That adversity it was an evidence against you. It was the training and it''s in your evidence log now"},{"start_s":7.56,"text":"Not history"},{"start_s":9.2,"text":"Just ammunition now that you''re finished day 29 is complete"}]}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000029';

-- Day 30: The Evidence
update public.lessons set
  duration_seconds = 308,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_30/lesson_30_seg_01.mp3"],"total_audio_seconds":86.91,"timed_text":[{"start_s":0.02,"text":"Day 30 you made it and I want to gloss over that because most people quit somewhere around day eight or 15"},{"start_s":9.38,"text":"Right when the novelty wears off and it starts feeling like work"},{"start_s":13.34,"text":"You kept showing up every single day. That is not a small thing"},{"start_s":19.15,"text":"Think about where you were when you started this"},{"start_s":21.75,"text":"What you didn''t have yet? No reset word no reset protocol no if then plan"},{"start_s":28.15,"text":"No visualization practice no evidence log no traffic light system no physical anchor"},{"start_s":34.79,"text":"No language for what was happening in your head when the pressure hit no connection to your why"},{"start_s":40.74,"text":"You have all of it now not because someone gave you to you"},{"start_s":45.02,"text":"Because you built it"},{"start_s":46.46,"text":"Rep by rep day by day"},{"start_s":48.82,"text":"Lesson by lesson the question. I want you to carry from here forward and the one that keeps athletes going"},{"start_s":55.89,"text":"After any program ends is this"},{"start_s":58.81,"text":"What''s next not how much did I improve not was it worth it? What''s next?"},{"start_s":66.27,"text":"Take that question into every season competition or every time you feel yourself starting to plateau"},{"start_s":73.24,"text":"Before you journal one last time. I want you to do one thing"},{"start_s":76.6,"text":"Open that visualization board"},{"start_s":78.68,"text":"Look at the athlete you committed to becoming then read your evidence log and see what you''ve actually done"}]},{"type":"program_completion","ambient_audio":"ambient/ambient_music.mp3","cards":[{"source":"profile.visualization_board","caption":"Open your visualization board. The athlete you committed to becoming on Day 23. Take your time."},{"source":"profile.evidence_log","caption":"Now your evidence log. Read it from the beginning. Not to compare — to see."},{"source":"static","text":"The distance between that board and where you stand right now? That''s the work. And you''ve already started closing it."},{"source":"static","text":"What''s next?"}]},{"type":"voiceover","audio_files":["lesson_30/lesson_30_seg_02.mp3"],"total_audio_seconds":41.78,"timed_text":[{"start_s":0.0,"text":"You don''t need a score to know it''s changed. You know it and how you showed up to practice"},{"start_s":4.51,"text":"this week, how you handled the last competition, how quickly you recovered after the last mistake,"},{"start_s":10.83,"text":"how differently you talked to yourself now than you did 30 days ago. That''s the evidence."},{"start_s":17.06,"text":"Keep the log, run the routine, use the tools, build on why you wrote on day 17."},{"start_s":25.09,"text":"And when competition gets hard and it will, remember that you''ve already been to the"},{"start_s":29.65,"text":"difficult places in here and you came out with a plan every single time. That''s it,"},{"start_s":36.85,"text":"programs over, but your training isn''t. Go compete like it."}]},{"type":"journal_prompt","prompt":"What is different about the way you think about competing now compared to where you started? What does the next chapter look like — and what''s your first move?"}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000030';

commit;